#include <algorithm>
#include <fstream>
#include <iostream>
#include <memory>
#include <string>
#include <vector>
using namespace std;
class Product{protected:int id;string name,category;double price;int stock;public:Product(int i,string n,string c,double p,int s):id(i),name(move(n)),category(move(c)),price(p),stock(s){}virtual~Product()=default;int getId()const{return id;}const string&getName()const{return name;}int getStock()const{return stock;}virtual double finalPrice()const{return price;}virtual string extra()const{return"";}bool reduce(int q){if(q<=0||q>stock)return false;stock-=q;return true;}void show()const{cout<<id<<" | "<<name<<" | "<<category<<" | "<<finalPrice()<<" | stock "<<stock<<" | "<<extra()<<'\n';}};
class Electronics:public Product{string brand;int warranty;public:Electronics(int i,string n,double p,int s,string b,int w):Product(i,move(n),"Electronics",p,s),brand(move(b)),warranty(w){}double finalPrice()const override{return price*1.05;}string extra()const override{return brand+", warranty "+to_string(warranty)+"m";}};class Clothing:public Product{string size,color;public:Clothing(int i,string n,double p,int s,string z,string c):Product(i,move(n),"Clothing",p,s),size(move(z)),color(move(c)){}double finalPrice()const override{return price*.9;}string extra()const override{return size+" "+color;}};class Book:public Product{string author;public:Book(int i,string n,double p,int s,string a):Product(i,move(n),"Book",p,s),author(move(a)){}string extra()const override{return author;}};
struct CartItem{shared_ptr<Product>p;int q;double subtotal()const{return p->finalPrice()*q;}};class Cart{vector<CartItem>items;public:void add(shared_ptr<Product>p,int q){if(!p||q<=0||q>p->getStock())throw runtime_error("invalid quantity");for(auto&x:items)if(x.p->getId()==p->getId()){if(x.q+q>p->getStock())throw runtime_error("insufficient stock");x.q+=q;return;}items.push_back({p,q});}void remove(int id){items.erase(remove_if(items.begin(),items.end(),[&](auto&x){return x.p->getId()==id;}),items.end());}void show()const{double t=0;for(auto&x:items){cout<<x.p->getName()<<" x"<<x.q<<" = "<<x.subtotal()<<'\n';t+=x.subtotal();}cout<<"Total "<<t<<'\n';}double checkout(){double t=0;for(auto&x:items)if(x.q>x.p->getStock())throw runtime_error("stock changed");for(auto&x:items){x.p->reduce(x.q);t+=x.subtotal();}items.clear();return t;}};
class Store{vector<shared_ptr<Product>>products;Cart cart;shared_ptr<Product>find(int id){for(auto&p:products)if(p->getId()==id)return p;return{};}public:Store(){products.push_back(make_shared<Electronics>(1,"Laptop",30000,5,"Nova",24));products.push_back(make_shared<Clothing>(2,"T-Shirt",500,20,"L","Black"));products.push_back(make_shared<Book>(3,"C++ Primer",1200,8,"Lippman"));}void list()const{for(auto&p:products)p->show();}void run(){for(;;){cout<<"\nE-Commerce\n1 Products 2 Add cart 3 Remove cart 4 View cart 5 Checkout 0 Exit\n";int c;if(!(cin>>c)||c==0)break;if(c==1)list();else if(c==2){int id,q;list();cin>>id>>q;try{cart.add(find(id),q);}catch(exception&e){cout<<e.what()<<'\n';}}else if(c==3){int id;cin>>id;cart.remove(id);}else if(c==4)cart.show();else if(c==5){try{double t=cart.checkout();cout<<"Paid "<<t<<'\n';ofstream("purchases.txt",ios::app)<<t<<'\n';}catch(exception&e){cout<<e.what()<<'\n';}}}}};int main(){Store{}.run();}
